parameters.jsCode:
const fetched = $('Fetch Article Content').item.json.data || '';
const manual = $('Extract Article Data').item.json.text;
const content = fetched || manual;
const truncated = content.substring(0, 4000);
return [{ json: { content: truncated, url: $('Extract Article Data').item.json.url, headline: $('Extract Article Data').item.json.headline } }];

